with u as (select 'owned.jpg'::text image_url, null::text before_image_url,'{"caption":"owned","credit":{"author":"A"},"provenance":{"source":"owned"}}'::jsonb image_meta,'{"caption":"","credit":null}'::jsonb before_image_meta), cases(label,image_url,image_meta,expected) as (values ('baseline',null::text,'{"caption":"","credit":null}'::jsonb,true),('rerun','owned.jpg','{"caption":"owned","credit":{"author":"A"},"provenance":{"source":"owned"}}'::jsonb,true),('extra-top-field-rerun','owned.jpg','{"caption":"owned","credit":{"author":"A"},"provenance":{"source":"owned"},"other":1}'::jsonb,true),('new-photo','user.jpg','{"caption":"","credit":null}'::jsonb,false),('new-credit',null::text,'{"caption":"","credit":{"author":"User"}}'::jsonb,false),('new-metadata',null::text,'{"caption":"","credit":null,"other":1}'::jsonb,false),('changed-owned-credit','owned.jpg','{"caption":"owned","credit":{"author":"User"},"provenance":{"source":"owned"}}'::jsonb,false),('nested-author-url','owned.jpg','{"caption":"owned","credit":{"author":"A","authorUrl":"https://example.com"},"provenance":{"source":"owned"}}'::jsonb,false),('nested-provenance','owned.jpg','{"caption":"owned","credit":{"author":"A"},"provenance":{"source":"owned","extraSources":["new"]}}'::jsonb,false)) select label,coalesce(((p.image_url is not distinct from u.before_image_url and coalesce(p.image_meta,'{}'::jsonb)=u.before_image_meta) or (p.image_url=u.image_url and (coalesce(p.image_meta,'{}'::jsonb)||u.image_meta)=coalesce(p.image_meta,'{}'::jsonb))),false)=expected as pass from cases p cross join u;

